'use strict';
let excerptBank=null,excerptLoadError=false,readingNeed='comfort',readingSource='any',allowChallenging=false;
let catalogMood='any',catalogNeed='any',catalogSource='any',excerptOrigin='passages';
const dismissedPassages=new Set(),openedPassages=new Set();
const readingNeeds=[['comfort','A little comfort','Thodi tasalli'],['perspective','A different perspective','Ek naya nazariya'],['understanding','Understand myself','Khud ko samajhna'],['action','One practical step','Ek chhota kadam']];
function needName(id){return readingNeeds.find(x=>x[0]===id)?.[1]||'Any reading need'}
function needChoices(){return `<div class="field">What would feel useful right now?</div><div class="chips">${readingNeeds.map(([id,label,h])=>`<button class="chip ${readingNeed===id?'selected':''}" data-reading-need="${id}" aria-pressed="${readingNeed===id}">${label}${hi(h)}</button>`).join('')}</div>`}
function bookOptions(value){return `<option value="any" ${value==='any'?'selected':''}>Any writer or book</option>${(sourceManifest?.sources||[]).map(s=>`<option value="${esc(s.id)}" ${value===s.id?'selected':''}>${esc(s.author)} · ${esc(s.title)}</option>`).join('')}`}
function readingPreferences(){return `<details class="reading-preferences"><summary>Choose a writer or include challenging literature</summary><label class="field" for="reading-source">A book you’re drawn to</label><select id="reading-source" class="section-select">${bookOptions(readingSource)}</select><label class="field"><input id="challenging-readings" type="checkbox" ${allowChallenging?'checked':''}>Include challenging literature</label><p class="small">Includes Kafka, Oedipus, Machiavelli, Nietzsche, and other passages marked as heavier reading. Each has its own context note. These are left out of suggestions at intensity 4–5.</p></details>`}
function sourceForExcerpt(entry){return sourceManifest?.sources?.find(s=>s.id===entry.sourceId)}
function excerptCard(result){const e=result.entry,s=sourceForExcerpt(e);if(!s)return '';const matches=result.matchedMoods.map(id=>moodData.find(m=>m.id===id)?.name||id);return `<div class="passage-card"><p class="small">${esc(s.author)}${e.sensitive?' · Challenging reading':''}</p><h3><a href="#excerpt/${encodeURIComponent(e.id)}">${esc(e.heading)}</a></h3><p class="small">${esc(s.title)}</p><p>${esc(e.why)}</p>${matches.length?`<p class="match-reason">Matched to ${matches.map(esc).join(' + ')}${result.matchedNeed?' and '+esc(needName(result.matchedNeed).toLowerCase()):''}${result.nuanceMatched?'; your selected nuance also fits':''}.</p>`:''}<div class="passage-actions"><a href="#excerpt/${encodeURIComponent(e.id)}">Read the passage</a><button class="text-btn" data-dismiss-passage="${esc(e.id)}">Try another</button></div></div>`}
function passageRecommendations(){if(excerptLoadError)return `<div class="panel"><h3>The passages couldn’t load.</h3><p>You can still use the quiet reset or library.</p>${button('Try loading the passages again','retry-passages','secondary')}</div>`;if(!excerptBank||!sourceManifest)return '<p class="note" role="status">Finding the source-linked passages…</p>';
 const ranked=AntarMatching.rank(excerptBank,{moods:selected,need:readingNeed,source:readingSource,nuance,intensity,allowChallenging,dismissed:[...dismissedPassages]});
 const seen=new Set();const choices=ranked.filter(r=>{if(readingSource==='any'&&seen.has(r.entry.sourceId))return false;seen.add(r.entry.sourceId);return true}).slice(0,2);
 return `<section aria-label="Passages for this moment"><div class="section-head"><h2>A passage for this moment</h2></div><p class="small">Selected feelings and reading needs guide these editorial matches. Your own words aren’t automatically interpreted.</p>${needChoices()}${readingPreferences()}${intensity>=4?'<p class="note">You marked this as hard to hold. The quiet reset comes first; only passages marked gentler can appear here.</p>':''}${choices.length?choices.map(excerptCard).join(''):`<div class="panel"><h3>No close match with these choices.</h3><p>Try a different reading need or writer, or take a quiet pause. We won’t substitute an unrelated passage.</p>${dismissedPassages.size?button('Show skipped suggestions again','restore-passages','secondary'):''}</div>`}<a href="#passages" class="text-btn">Explore excerpts across the whole library</a></section>`}
function passageCatalog(){if(!excerptBank||!sourceManifest)return `${button('‹ Book shelf','go-library','back')}<h1>Passages for your feelings.</h1><p class="sub" role="status">${excerptLoadError?'The passages could not load.':'Loading the passage index…'}</p>${excerptLoadError?button('Try again','retry-passages'):''}`;
 const all=AntarMatching.rank(excerptBank,{moods:catalogMood==='any'?[]:[catalogMood],need:catalogNeed,source:catalogSource,intensity,allowChallenging,dismissed:[...dismissedPassages]});
 return `${button('‹ Book shelf','go-library','back')}<h1>Words to explore with.</h1><p class="sub">${excerptBank.length} verified passages across ${new Set(excerptBank.map(e=>e.sourceId)).size} source editions.${hi('Har passage ka source milega. Jo fit na ho, use chhod sakte ho.')}</p><label class="field" for="passage-mood">A feeling to explore</label><select id="passage-mood" class="section-select"><option value="any">Any feeling</option>${moodData.map(m=>`<option value="${m.id}" ${catalogMood===m.id?'selected':''}>${m.name}${bilingual?' · '+m.hi:''}</option>`).join('')}</select><label class="field" for="passage-need">What you want from the reading</label><select id="passage-need" class="section-select"><option value="any">Any reading need</option>${readingNeeds.map(([id,label])=>`<option value="${id}" ${catalogNeed===id?'selected':''}>${label}</option>`).join('')}</select><label class="field" for="passage-source">Writer or book</label><select id="passage-source" class="section-select">${bookOptions(catalogSource)}</select><label class="field"><input id="catalog-challenging" type="checkbox" ${allowChallenging?'checked':''}>Include challenging literature</label><p class="small">The filter respects your current intensity (${intensity}/5). Challenging passages are excluded from suggestions at 4–5. You can always browse the original books separately.</p><div class="section-head"><h2>${all.length} ${all.length===1?'passage':'passages'}</h2></div>${all.length?all.map(excerptCard).join(''):'<div class="panel"><p>No close match for these filters. Try another feeling, reading need, or book.</p></div>'}<p class="note">These are editorial connections between literature and everyday feelings. They do not diagnose a condition or establish that a reading will improve your mood.</p>`}
function excerptView(id){if(!excerptBank||!sourceManifest)return `${button('‹ Passages','go-passages','back')}<h1>A passage for this moment.</h1><p class="sub" role="status">${excerptLoadError?'The passage could not load.':'Loading the source-linked reading…'}</p>${excerptLoadError?button('Try again','retry-passages'):''}`;const e=excerptBank.find(e=>e.id===id),s=e&&sourceForExcerpt(e);if(!s)return notFound();const sourceIndex=sourceManifest.sources.findIndex(s=>s.id===e.sourceId);const consent=!e.sensitive||allowChallenging||openedPassages.has(e.id);
 return `${button('‹ Passages','go-passages','back')}<p class="greeting">${esc(s.author)}</p><h1>${esc(e.heading)}</h1><p class="sub">${esc(s.title)} · ${esc(s.translator||'original text')}</p>${e.sensitive?`<div class="warning"><strong>A heavier reading</strong><p>${esc(e.contentNote||s.contentNote)}</p></div>`:''}${!consent?`<div class="panel"><p>This passage is optional. It is literature to reflect on, not advice to follow.</p>${button('Choose to read this passage','open-passage:'+e.id,'secondary')}${button('Find a gentler reading','gentler-passages','text-btn')}</div>`:`<p class="small">Exact excerpt from the downloaded edition. ${esc(e.locator)}.</p>${s.licenseNotice?`<details class="license-notice" open><summary>Source licence and reuse notice</summary><p>${esc(s.licenseNotice)}</p><a href="${esc(s.licenseUrl)}" target="_blank" rel="noopener">Read the full Project Gutenberg License</a></details>`:''}<blockquote class="excerpt-quote">${esc(e.quote)}</blockquote><p class="source">${esc(s.author)} · ${esc(s.title)} · ${esc(s.translator||'')}.<br>${esc(e.locator)}</p>${bilingual?`<div class="panel"><h3>Hinglish mein samjhein</h3><p>${esc(e.hinglish)}</p><p class="small">An informal interpretation written for Antar; not a literal translation.</p></div>`:''}<h2>Why this might fit</h2><p class="sub">${esc(e.why)}</p><div class="chips">${e.moods.map(id=>`<span class="tag">${esc(moodData.find(m=>m.id===id)?.name||id)}</span>`).join('')}</div><h2>A question you can leave open</h2><p class="sub">${esc(e.prompt)}</p>${button('Keep this reflection in my anchors','keep-passage:'+e.id,'secondary')}<p class="small">Saves the app’s reflection and attribution, not a record of your selected mood.</p><div class="passage-actions"><button class="text-btn" data-dismiss-passage="${esc(e.id)}">This doesn’t fit · try another</button><a href="#source/${sourceIndex}/${e.sectionIndex}/${encodeURIComponent(e.id)}">See the highlighted passage in its chapter</a></div><details><summary>About this source and interpretation</summary><p class="small">${esc(s.edition)}. ${esc(s.rights)}</p><a href="${esc(e.sourceUrl||s.sourceUrl)}" target="_blank" rel="noopener">Read the source edition online</a><p class="note">Mood tags and Hinglish explanations are editorial interpretations. No diagnosis or therapeutic effect is inferred from a text.</p></details>`}`}
function relatedPassages(sourceId){if(!excerptBank)return '';const entries=excerptBank.filter(e=>e.sourceId===sourceId);return entries.length?`<details><summary>Explore this book through feelings</summary><p class="small">Original passages with Hinglish interpretations and source locations.</p><div class="sources-list">${entries.map(e=>`<a href="#excerpt/${encodeURIComponent(e.id)}">${esc(e.heading)}</a>`).join('')}</div></details>`:''}
async function loadPassages(){excerptLoadError=false;try{const r=await fetch('library/excerpts.json');if(!r.ok)throw Error();const d=await r.json();if(!Array.isArray(d.entries)||!d.entries.length)throw Error();excerptBank=d.entries;}catch{excerptLoadError=true;}if(['support','passages','library'].includes(route)||route.startsWith('excerpt/')||route.startsWith('source/'))render(true)}
document.addEventListener('click',e=>{const link=e.target.closest('a[href^="#excerpt/"]');if(link){excerptOrigin=route==='support'?'support':'passages';return}const el=e.target.closest('button');if(!el)return;
 if(el.dataset.readingNeed){readingNeed=el.dataset.readingNeed;dismissedPassages.clear();render(true);return}
 if(el.dataset.dismissPassage){dismissedPassages.add(el.dataset.dismissPassage);if(route.startsWith('excerpt/'))go(excerptOrigin);else render(true);toast('We’ll offer another passage if one fits.');return}
 const action=el.dataset.action||'';
 if(action==='retry-passages'){loadPassages();return}
 if(action==='restore-passages'){dismissedPassages.clear();render(true);return}
 if(action==='gentler-passages'){allowChallenging=false;catalogSource='any';go('passages');return}
 if(action.startsWith('open-passage:')){openedPassages.add(action.slice(13));render(true);return}
 if(action.startsWith('keep-passage:')){const entry=excerptBank?.find(x=>x.id===action.slice(13));if(entry){const s=sourceForExcerpt(entry);saveAnchor(entry.heading+': '+entry.prompt+' — Reflection with '+s.author);}return}
});
document.addEventListener('change',e=>{if(e.target.id==='reading-source'){readingSource=e.target.value;dismissedPassages.clear();render(true)}if(['challenging-readings','catalog-challenging'].includes(e.target.id)){allowChallenging=e.target.checked;render(true)}if(e.target.id==='passage-mood'){catalogMood=e.target.value;render(true)}if(e.target.id==='passage-need'){catalogNeed=e.target.value;render(true)}if(e.target.id==='passage-source'){catalogSource=e.target.value;render(true)}});
